import io
import unittest

def retained(q, p, r):
    if not 0 <= r <= q:
        raise ValueError("invalid return")
    return (q - r) * p

class RetainedTests(unittest.TestCase):
    def test_partial(self):
        self.assertEqual(retained(3, 100, 1), 200)
    def test_full(self):
        self.assertEqual(retained(3, 100, 3), 0)
    def test_invalid(self):
        with self.assertRaises(ValueError):
            retained(3, 100, 4)

result = unittest.TextTestRunner(stream=io.StringIO()).run(
    unittest.defaultTestLoader.loadTestsFromTestCase(RetainedTests))
print(result.testsRun)
print(result.wasSuccessful())

import math

def valid_share(value, expected):
    return (type(value) in (int, float) and math.isfinite(value)
            and 0 <= value <= 1
            and math.isclose(value, expected, rel_tol=1e-12, abs_tol=1e-12))

for value in (0.1 + 0.2, float("nan"), float("inf"), True):
    print(valid_share(value, 0.3))
